import { ButtonGroupContext, ButtonGroupContextValue, POSITIONTAG } from '@src/components/ks-button-group/context';
import { Vue2ValueFix } from '@src/framework/decorators';
import { Consume } from '@src/framework/runtime-context';
import { Component, type ComponentInterface, Element, Host, Prop, State, h } from '@stencil/core';
import { KsIconCheckMarkSmall } from '@fe-infra/keystone-icons-stencil';

const prefix = 'button-group-item';

/**
 * @slot default - Label or custom content rendered inside the button group item.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-button-group-item',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsButtonGroupItem implements ComponentInterface {
  @Element() el!: HTMLKsButtonGroupItemElement;

  @Consume({
    context: ButtonGroupContext,
    subscribe: true,
    path: ['value'],
  })
  @State()
  valueFromButtonGroup: ButtonGroupContextValue['value'];
  @Consume({
    context: ButtonGroupContext,
    subscribe: true,
    path: ['disabled'],
  })
  @State()
  disabledFromButtonGroup: ButtonGroupContextValue['disabled'];
  @Consume({
    context: ButtonGroupContext,
    subscribe: true,
    path: ['multiple'],
  })
  @State()
  multipleFromButtonGroup: ButtonGroupContextValue['multiple'];
  @Consume({
    context: ButtonGroupContext,
    subscribe: true,
    path: ['positionMap'],
  })
  @State()
  positionMapFromButtonGroup: ButtonGroupContextValue['positionMap'];
  @Consume({
    context: ButtonGroupContext,
    path: ['onValueChange'],
  })
  private onValueChangeFromButtonGroup!: ButtonGroupContextValue['onValueChange'];

  /** The value of the button group item. */
  @Prop() @Vue2ValueFix() value?: string;
  /** Indicates whether the button group item is disabled. When `true`, the user will not be able to interact with the button. */
  @Prop() disabled?: boolean;
  /** Indicates whether a selected item hides its checkmark icon when `multiple` is enabled. */
  @Prop() hideCheckmark?: boolean;

  private handleClick() {
    const disabled = this.disabledFromButtonGroup || this.disabled || false;
    if (this.value && !disabled) {
      this.onValueChangeFromButtonGroup(this.value);
    }
  }

  get selected() {
    if (this.valueFromButtonGroup && this.value) {
      return this.valueFromButtonGroup.includes(this.value);
    }
    return false;
  }

  get position() {
    return this.positionMapFromButtonGroup?.get(this.el);
  }

  render() {
    const disabled = this.disabledFromButtonGroup || this.disabled || false;
    const classes = {
      [prefix]: true,
      [`${prefix}__selected`]: this.selected,
      [`${prefix}__disabled`]: disabled,
      [`${prefix}__start`]: this.position === POSITIONTAG.START,
      [`${prefix}__end`]: this.position === POSITIONTAG.END,
      [`${prefix}__multiple`]: this.multipleFromButtonGroup || false,
    };
    return (
      <Host class="KsButtonGroupItem">
        <div
          class={classes}
          id="item"
          part="base"
          onClick={this.handleClick.bind(this)}
          onKeyPress={this.handleClick.bind(this)}
          data-testid="ks-button-group-item-index-wfoNyD"
        >
          <input />
          <ks-text class={`${prefix}-text`} variant="labelLg" color="inherit">
            <span class="label">
              <slot />
              {this.multipleFromButtonGroup && this.selected && !this.hideCheckmark && (
                <KsIconCheckMarkSmall class={`${prefix}__selected-icon`} />
              )}
            </span>
          </ks-text>
        </div>
      </Host>
    );
  }
}
